#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=2
ENV_FILE=".env.cron-secret.local"
REPO_URL="https://github.com/benlucas27/tons-of-consequence.git"
CRON_SECRET_VALUE="38bbf3a760b181b17e20d7fe768daec31e9dd3653eeb0efb"

banner "Unblock last night's deploy"
say "Two things are stopping the work already committed locally from reaching"
say "production: no git push access here, and the new cron endpoint has no"
say "auth secret set on Vercel yet. This walks you through both."

# ── Stage 1: git push access ────────────────────────────────────────────
stage "GitHub push access"
say "This machine has no valid GitHub credentials and no SSH key GitHub"
say "recognizes — that's why the 4 commits sitting in the local clone never"
say "reached origin/main."

if command -v gh >/dev/null 2>&1; then
  if gh auth status >/dev/null 2>&1; then
    say "gh is already authenticated:"
    gh auth status || true
  else
    say "The gh CLI is installed but not authenticated. This is the easiest path:"
    step "Run: gh auth login"
    step "Choose GitHub.com → HTTPS → 'Login with a web browser' → follow the code/URL it gives you."
    pause "Run that in another terminal now, then come back and press Enter."
    if gh auth status >/dev/null 2>&1; then
      say "  ✓ gh is now authenticated."
    else
      warn "gh still isn't authenticated — you can retry gh auth login, or use the SSH path below instead."
    fi
  fi
else
  warn "gh CLI isn't installed. Falling back to an SSH key."
  step "Install gh later if you want (brew install gh), or continue with SSH now."
fi

if ! (command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1); then
  say ""
  say "SSH key path:"
  SSH_KEY="$HOME/.ssh/id_ed25519"
  if [[ -f "$SSH_KEY.pub" ]]; then
    say "Found an existing key at $SSH_KEY.pub — checking if GitHub already has it."
  else
    step "Generating a new SSH key (press Enter through the prompts for no passphrase, or set one)."
    ssh-keygen -t ed25519 -C "tons-of-consequence-deploy" -f "$SSH_KEY"
  fi
  say "Your public key:"
  cat "$SSH_KEY.pub"
  open_url "https://github.com/settings/ssh/new"
  step "Paste the public key above into 'Key', give it a title (e.g. 'tons-of-consequence deploy'), click 'Add SSH key'."
  pause "Done? Press Enter to test the connection."
  if ssh -o StrictHostKeyChecking=accept-new -T git@github.com 2>&1 | grep -qi "successfully authenticated"; then
    say "  ✓ SSH authentication to GitHub works."
    if git -C "$(dirname "$0")/.." remote get-url origin | grep -q "^https://"; then
      step "Switching the repo's remote from HTTPS to SSH so pushes use this key."
      git -C "$(dirname "$0")/.." remote set-url origin "git@github.com:benlucas27/tons-of-consequence.git"
    fi
  else
    warn "SSH test didn't confirm success — re-run this stage after fixing, or push manually."
  fi
fi

say ""
if confirm "Push the 4 local commits to origin/main now?"; then
  if git -C "$(dirname "$0")/.." push origin main; then
    say "  ✓ Pushed. Vercel should start a new deployment within a minute or two."
  else
    warn "Push failed — resolve the auth error above and re-run this script."
    SKIPPED+=("git push origin main (run it by hand once auth is fixed)")
  fi
else
  note "Skipped — push manually later with: git push origin main"
  SKIPPED+=("git push origin main")
fi

# ── Stage 2: CRON_SECRET on Vercel ──────────────────────────────────────
stage "Vercel CRON_SECRET"
say "The new /api/cron/refresh-centuries endpoint checks for this env var and"
say "rejects requests without it — right now it's unset, so the endpoint is"
say "open to anyone. This adds it."
write_env CRON_SECRET "$CRON_SECRET_VALUE"
note "(saved to $ENV_FILE for your reference — this file is gitignored)"

open_url "https://vercel.com/plannerapp22s-projects/tons-of-consequence/settings/environment-variables"
step "Click 'Add Environment Variable'."
step "Type: Secret. Key: CRON_SECRET"
step "Value: $CRON_SECRET_VALUE"
step "Apply to All Environments, then Save."
pause "Done? Press Enter to verify."

if confirm "Has the site redeployed since you added it (check the Deployments tab)?"; then
  say "Checking the endpoint rejects an unauthenticated request..."
  if code=$(curl -s -o /dev/null -w '%{http_code}' "https://tons-of-consequence.vercel.app/api/cron/refresh-centuries" 2>/dev/null); then
    if [[ "$code" == "401" ]]; then
      say "  ✓ Got 401 Unauthorized — CRON_SECRET is active."
    else
      warn "Got HTTP $code instead of 401 — either it hasn't redeployed yet, or something's off. Re-check in a minute."
    fi
  else
    warn "Couldn't reach the endpoint to verify — check it by hand once deployed."
  fi
else
  note "Redeploy first (push a commit, or click Redeploy in Vercel), then re-run this stage to verify."
fi

finish
say "This script did its job — safe to delete: rm scripts/unblock-deploy.sh"
